function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 50) return 'grid needs 1 to 50 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 50) return 'Each row needs 1 to 50 cells.';
  for (const row of grid) {
    if (row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Each cell is 0 or 1.';
  }
  return null;
}

