function numDistinctIslands(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const seen = grid.map(row => row.map(() => false));
  const shapes = new Set();

  function explore(r, c, startRow, startCol, cells) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) {
      return;
    }
    if (grid[r][c] === 0 || seen[r][c]) {
      return;
    }
    seen[r][c] = true;
    cells.push(`${r - startRow},${c - startCol}`);
    explore(r + 1, c, startRow, startCol, cells);
    explore(r - 1, c, startRow, startCol, cells);
    explore(r, c + 1, startRow, startCol, cells);
    explore(r, c - 1, startRow, startCol, cells);
  }

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 1 && !seen[r][c]) {
        const cells = [];
        explore(r, c, r, c, cells);
        shapes.add(cells.join(' '));
      }
    }
  }
  return shapes.size;
}

