function numDistinctIslands(grid) {
  // Collect each island with BFS, move it so its minimum row and column are 0, and sort its cells.
  const m = grid.length, n = grid[0].length;
  const label = grid.map(row => row.map(() => -1));
  const found = [];
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] !== 1 || label[i][j] !== -1) continue;
      const island = [[i, j]];
      label[i][j] = found.length;
      for (let k = 0; k < island.length; k++) {
        const [x, y] = island[k];
        for (const [a, b] of [[x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]]) {
          if (a >= 0 && a < m && b >= 0 && b < n && grid[a][b] === 1 && label[a][b] === -1) {
            label[a][b] = found.length;
            island.push([a, b]);
          }
        }
      }
      const minRow = Math.min(...island.map(p => p[0]));
      const minCol = Math.min(...island.map(p => p[1]));
      const normal = island.map(([x, y]) => (x - minRow) * 1000 + (y - minCol)).sort((p, q) => p - q);
      found.push(normal);
    }
  }
  const distinct = [];
  for (const shape of found)
    if (!distinct.some(other => other.length === shape.length && other.every((v, t) => v === shape[t]))) distinct.push(shape);
  return distinct.length;
}

