function generate(rand, size) {
  const m = size === 'large' ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 5);
  const density = rand() < 0.15 ? (rand() < 0.5 ? 0 : 0.9) : 0.2 + rand() * 0.5;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  if (size === 'large' && rand() < 0.5) {
    // Stamp a few small shapes repeatedly on a water background so many islands repeat.
    for (const row of grid) row.fill(0);
    const stamps = Array.from({ length: 4 }, () => Array.from({ length: 3 }, () => Array.from({ length: 3 }, () => (rand() < 0.6 ? 1 : 0))));
    for (let r = 0; r + 3 <= m; r += 4) {
      for (let c = 0; c + 3 <= n; c += 4) {
        const stamp = stamps[Math.floor(rand() * stamps.length)];
        for (let dr = 0; dr < 3; dr++) for (let dc = 0; dc < 3; dc++) grid[r + dr][c + dc] = stamp[dr][dc];
      }
    }
  }
  return [grid];
}
